"""Bounded ZIP decoder for CI-generated byte fixtures ONLY.

No paths, extraction, filesystem, subprocesses, network, IPC or real mods.
This is not a production-safe reader of untrusted user archives.
"""
from __future__ import annotations
import io
import re
import stat
import zipfile

from controlled_definition_hints import SUPPORTED, TEXT_LIMIT, inspect_fixture_text
from controlled_reference_hints import (
    empty_counts, inspect_fixture_references, FixtureReferenceLimitExceeded,
    MAX_REFERENCES_ALL
)

MAX_ARCHIVE_BYTES = 2_000_000
MAX_EXPANDED_BYTES = 4_000_000
MAX_ENTRIES = 128
MAX_ENTRY_PATH = 160
MAX_DEPTH = 12
MAX_RATIO = 100
CHUNK = 16_384
# Fixed output schema. These are filename SUFFIXES only, never parsed format
# evidence or an identification of the target simulator.
SUFFIXES = (
    "bus", "cfg", "sco", "sli", "sii", "scs", "dds",
    "png", "jpg", "wav", "ogg", "bank", "json", "other"
)
VALID_NAME = re.compile(r"[A-Za-z0-9_./-]+\Z", re.ASCII)
RESERVED = re.compile(r"(?:con|prn|aux|nul|com[1-9]|lpt[1-9])(?:\..*)?\Z", re.IGNORECASE)

class ControlledZipRefused(ValueError):
    pass

def refuse():
    raise ControlledZipRefused("CONTROLLED_ZIP_BYTES_REFUSED")

def examine_controlled_zip_bytes(payload: bytes) -> dict:
    """Return only aggregate measurements and explicit negative assurances."""
    if type(payload) is not bytes or not (0 < len(payload) <= MAX_ARCHIVE_BYTES):
        refuse()
    declared = actual = files = dirs = 0
    seen: set[str] = set()
    file_names: set[str] = set()
    suffix_counts = {suffix: 0 for suffix in SUFFIXES}
    # Source text is retained only in this function, after ZIP entry budgets
    # and before its aggregate response. Never returned, persisted or logged.
    fixture_sources = []
    references = empty_counts()
    reference_sources = {"inspected": 0, "notInspected": 0}
    definition_hints = {
        suffix: {
            "declaredFiles": 0, "markerObserved": 0, "noMarker": 0,
            "textUnavailable": 0, "notInspected": 0
        } for suffix in ("bus", "cfg", "sii")
    }
    # Private, package-local grouping. Full paths and vehicle folder names
    # never appear in the returned report. Markers are NOT format proof.
    bus_marker_folders: set[str] = set()
    cfg_marker_folders: set[str] = set()
    # Private to this invocation: all names are already screened ZIP entries.
    # Linking must target an independently marker-bearing CFG entry, not just
    # another file with a .cfg suffix in the same folder.
    bus_marker_paths: set[str] = set()
    cfg_marker_paths: set[str] = set()
    linked_vehicle_folders: set[str] = set()
    # M8: a model CFG can strengthen the fixture hint only if a bounded
    # [mesh] reference resolves to a separate O3D entry in the same variant.
    mesh_backed_cfg_paths: set[str] = set()
    mesh_linked_vehicle_folders: set[str] = set()
    truck_sii_marker_count = 0
    try:
        with zipfile.ZipFile(io.BytesIO(payload)) as zf:
            infos = zf.infolist()
            if len(infos) > MAX_ENTRIES:
                refuse()
            for info in infos:
                name = info.filename
                if (not name or len(name) > MAX_ENTRY_PATH or
                    not VALID_NAME.fullmatch(name) or name.startswith("/") or
                    "\\" in name or "//" in name or ":" in name):
                    refuse()
                is_dir = info.is_dir()
                parts = name.rstrip("/").split("/")
                if len(parts) > MAX_DEPTH or any(
                    not part or part in (".", "..") or part.endswith(".") or
                    RESERVED.fullmatch(part) for part in parts
                ):
                    refuse()
                normalized = "/".join(parts).lower()
                if normalized in seen:
                    refuse()
                seen.add(normalized)
                kind = stat.S_IFMT(info.external_attr >> 16)
                if kind not in (0, stat.S_IFDIR if is_dir else stat.S_IFREG):
                    refuse()
                if info.flag_bits & 1 or info.compress_type not in (
                    zipfile.ZIP_STORED, zipfile.ZIP_DEFLATED
                ):
                    refuse()
                if info.file_size < 0 or info.compress_size < 0:
                    refuse()
                if is_dir:
                    if info.file_size != 0 or info.compress_size != 0:
                        refuse()
                    dirs += 1
                    continue
                if (info.file_size > MAX_EXPANDED_BYTES or
                    (info.file_size > 0 and info.compress_size == 0) or
                    info.file_size > info.compress_size * MAX_RATIO):
                    refuse()
                declared += info.file_size
                if declared > MAX_EXPANDED_BYTES:
                    refuse()
                file_names.add(normalized)
                # Only an aggregate count derived from a *declared filename*.
                # Never expose names, roots, original case or full paths.
                last = parts[-1].lower()
                extension = last.rsplit(".", 1)[-1] if "." in last else ""
                suffix_counts[extension if extension in suffix_counts else "other"] += 1
                if extension in definition_hints:
                    definition_hints[extension]["declaredFiles"] += 1
                files += 1
            for name in seen:
                parts = name.split("/")
                if any("/".join(parts[:i]) in file_names for i in range(1, len(parts))):
                    refuse()
            # Read every entry to verify actual DEFLATE data and CRC,
            # with hard output accounting; no extraction to filesystem.
            for info in infos:
                if info.is_dir():
                    continue
                per_file = 0
                ext = info.filename.rsplit(".", 1)[-1].lower()
                small_definition = ext in SUPPORTED and info.file_size <= TEXT_LIMIT
                sample = bytearray() if small_definition else None
                with zf.open(info) as source:
                    while True:
                        chunk = source.read(CHUNK)
                        if not chunk:
                            break
                        per_file += len(chunk)
                        actual += len(chunk)
                        if per_file > info.file_size or actual > MAX_EXPANDED_BYTES:
                            refuse()
                        if sample is not None:
                            sample.extend(chunk)
                if per_file != info.file_size:
                    refuse()
                if ext in ("bus", "cfg"):
                    fixture_sources.append((info.filename.lower(), ext,
                                            bytes(sample) if sample is not None else None))
                if ext in definition_hints:
                    result = (inspect_fixture_text(ext, bytes(sample))
                              if sample is not None else "not-inspected")
                    column = {
                        "marker-observed": "markerObserved",
                        "no-marker": "noMarker",
                        "text-unavailable": "textUnavailable",
                        "not-inspected": "notInspected"
                    }[result]
                    definition_hints[ext][column] += 1
                    if result == "marker-observed":
                        parts = info.filename.lower().split("/")
                        if (ext in ("bus", "cfg") and len(parts) >= 3 and
                            parts[0] == "vehicles"):
                            folder = "/".join(parts[:2])
                            if ext == "bus":
                                bus_marker_folders.add(folder)
                                bus_marker_paths.add(info.filename.lower())
                            else:
                                cfg_marker_folders.add(folder)
                                cfg_marker_paths.add(info.filename.lower())
                        elif (ext == "sii" and len(parts) >= 2 and
                              parts[0] == "def"):
                            truck_sii_marker_count += 1
            # Cross-check ONLY against archive-internal file names already
            # accepted by the gate, never the user's game installation.
            vetted = frozenset(file_names)
            # The same bounded interpreter handles the tiny [mesh] -> O3D
            # dialect. Only CFGs with their own text marker are eligible.
            # The targets MUST be separate ZIP entries under this variant;
            # merely declaring the mesh or referencing another variant
            # cannot qualify. Keep paths private to this one invocation.
            for source, suffix, content in fixture_sources:
                if suffix != "cfg" or source not in cfg_marker_paths or content is None:
                    continue
                variant = "/".join(source.split("/")[:2])
                mesh_targets = frozenset(path for path in file_names
                                         if path.startswith(variant + "/")
                                         and path.endswith(".o3d"))
                if not mesh_targets:
                    continue
                mesh_hints = inspect_fixture_references("cfg", content,
                                                        source, mesh_targets)
                if (mesh_hints is not None and
                        mesh_hints["mesh"]["presentInFixture"] > 0):
                    mesh_backed_cfg_paths.add(source)
            # The existing bounded reference interpreter validates the exact
            # tiny [model] -> next line dialect. Reuse it with a restricted
            # index of marked CFG targets rather than creating another parser.
            for source, suffix, content in fixture_sources:
                hints = (inspect_fixture_references(suffix, content, source, vetted)
                         if content is not None else None)
                if hints is None:
                    reference_sources["notInspected"] += 1
                    continue
                reference_sources["inspected"] += 1
                for kind, counts in hints.items():
                    for key, count in counts.items():
                        references[kind][key] += count
                if sum(v["declared"] for v in references.values()) > MAX_REFERENCES_ALL:
                    refuse()
                if suffix != "bus" or source not in bus_marker_paths:
                    continue
                variant = "/".join(source.split("/")[:2])
                marked_targets = frozenset(path for path in cfg_marker_paths
                                           if path.startswith(variant + "/"))
                if not marked_targets:
                    continue
                linked = inspect_fixture_references("bus", content, source,
                                                     marked_targets)
                if linked is not None and linked["model"]["presentInFixture"] > 0:
                    linked_vehicle_folders.add(variant)
                    backed_targets = frozenset(path for path in mesh_backed_cfg_paths
                                               if path.startswith(variant + "/"))
                    if backed_targets:
                        backed = inspect_fixture_references("bus", content, source,
                                                            backed_targets)
                        if (backed is not None and
                                backed["model"]["presentInFixture"] > 0):
                            mesh_linked_vehicle_folders.add(variant)
    except FixtureReferenceLimitExceeded:
        refuse()
    except (zipfile.BadZipFile, zipfile.LargeZipFile, RuntimeError,
            EOFError, OSError, NotImplementedError, OverflowError,
            MemoryError):
        refuse()
    return {
        "source": "ci-generated-zip-bytes",
        "fileCount": files,
        "directoryCount": dirs,
        "actualInflatedBytes": actual,
        "zipHeadersAndCrcRead": True,
        "declaredSuffixCounts": suffix_counts,
        "declaredSuffixesAreContentProof": False,
        "definitionFixtureHints": definition_hints,
        "fixtureGameHints": {
            "omsiPairedVehicleFolders": len(bus_marker_folders & cfg_marker_folders),
            "omsiLinkedVehicleFolders": len(linked_vehicle_folders),
            "omsiMeshLinkedVehicleFolders": len(mesh_linked_vehicle_folders),
            "omsiLinkedWithoutMeshFolders": len(linked_vehicle_folders
                                                - mesh_linked_vehicle_folders),
            "omsiUnlinkedPairedFolders": len((bus_marker_folders & cfg_marker_folders)
                                            - linked_vehicle_folders),
            "omsiBusMarkerFolders": len(bus_marker_folders),
            "omsiCfgMarkerFolders": len(cfg_marker_folders),
            "truckSiiDefinitionMarkers": truck_sii_marker_count,
            "realFormatVerified": False,
            "gameRecognized": False,
        },
        "definitionSyntaxVerified": False,
        "fixtureReferenceCounts": references,
        "fixtureReferenceSources": reference_sources,
        "fixtureReferencesVerified": False,
        "archiveOriginVerified": False,
        "gameRecognized": False,
        "compatibilityVerified": False,
        "installationEnabled": False,
        "realGameFilesTouched": False,
    }
